<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { api } from '@/app/runtime'; import { useAsync } from '@/composables/useAsync'; import type { ExhibitionDetail } from '@/api/types';
const route = useRoute(); const router = useRouter(); const query = useAsync<ExhibitionDetail>(); const error = ref(''); const saving = ref(false); const form = reactive({ title: '', venue: '', date: '', time: '', category: '', status: 'optional', description: '', descriptionFormat: 'markdown' });
onMounted(async () => { if (route.params.id) { const data = await query.run(() => api.exhibitions.get(String(route.params.id))); if (data?.exhibition) Object.assign(form, data.exhibition); } });
async function save() { error.value = ''; saving.value = true; try { await api.exhibitions.save({ ...form, ...(route.params.id ? { id: String(route.params.id) } : {}) }); await router.replace('/exhibitor'); } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } finally { saving.value = false; } }
</script>
<template><section class="page"><button class="text-action" @click="router.back()">返回</button><h1>{{ route.params.id ? '编辑展会' : '新建展会' }}</h1><form class="card form" @submit.prevent="save"><label>名称<input v-model="form.title" required maxlength="60"></label><label>地点<input v-model="form.venue" required maxlength="60"></label><label>日期<input v-model="form.date" required type="date"></label><label>时间<input v-model="form.time" required></label><label>分类<input v-model="form.category"></label><label>报名方式<select v-model="form.status"><option value="optional">无需审核</option><option value="review">需审核</option><option value="display">仅展示</option></select></label><label>Markdown 简介<textarea v-model="form.description" rows="8"></textarea></label><p v-if="error" class="error">{{ error }}</p><button class="cta" :disabled="saving">保存展会</button></form></section></template>
